def passengers_to_requests(apps, schema_editor):
    """Passengers who joined before requests existed become accepted requests."""
    Ride = apps.get_model("test_app", "Ride")
    RideRequest = apps.get_model("test_app", "RideRequest")
    RideRequest.objects.bulk_create([
        RideRequest(ride_id=link.ride_id, passenger_id=link.user_id, status="accepted")
        for link in Ride.passenger.through.objects.all()
    ])


def requests_to_passengers(apps, schema_editor):
    Ride = apps.get_model("test_app", "Ride")
    RideRequest = apps.get_model("test_app", "RideRequest")
    Ride.passenger.through.objects.bulk_create([
        Ride.passenger.through(ride_id=request.ride_id, user_id=request.passenger_id)
        for request in RideRequest.objects.filter(status="accepted")
    ])


